            accept: [['^(prisons|the prison system|a prison system|governments)( should| must)\\b'], ['combine|join|pair|mix'], ['loss of (freedom|liberty)|punishment|prison sentences?'], ['with (compulsory|required|mandatory|obligatory)? ?(programmes|programs|courses|classes|training|therapy|education|reform)']],
